import{_ as a,c as n,a as s,o as l}from"./app-B9IyngIV.js";const i={};function t(r,e){return l(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_2025年实习第一阶段总结" tabindex="-1"><a class="header-anchor" href="#_2025年实习第一阶段总结"><span>2025年实习第一阶段总结</span></a></h1><div style="background:#f8f9fa;padding:12px 16px;border-left:3px solid #4CAF50;margin-bottom:16px;border-radius:0 4px 4px 0;font-size:0.9rem;"><div style="display:flex;align-items:center;gap:30px;flex-wrap:wrap;"><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">📅</span><span>2025-04-07</span></div><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">✍️</span><span>Jixer</span></div></div></div><p>不知不觉来公司已经实习了半年了，2025年第一季度已过，正好 IDP 也有这方面的需求，于是在此提笔写下总结</p><h2 id="系统熟悉度" tabindex="-1"><a class="header-anchor" href="#系统熟悉度"><span>系统熟悉度</span></a></h2><p>目前系统上熟悉的模块有 E-Learning 、E-Recruitment，这两个模块均是参与过从0到1开发。此外对于其他模块如：新契约（NB），销售渠道（SC）等都有一定的了解，在以后还多需要加入到这些模块的需求开发中去，才能更好的了解业务的上下文关系。</p><h2 id="专业技能" tabindex="-1"><a class="header-anchor" href="#专业技能"><span>专业技能</span></a></h2><p>对于专业技能方面，比较熟悉是 Java、SSM、SpringBoot、MyBatis 等日常开发的框架，公司使用的 groovy 语言语法在使用过程中也变得逐渐上手熟练。相对于比较薄弱的专业技能是 Elasticsearch，我了解到的公司系统对于 es 的使用只在于通过 es 来查出索引，通过索引再来查数据库，没用将 es 的核心搜索使用到，在以后还需要多了解公司对 es 的使用，并知晓为啥要这样用。</p><h2 id="个人感受" tabindex="-1"><a class="header-anchor" href="#个人感受"><span>个人感受</span></a></h2><p>在开发 E-learning 中，用到了一些技术点给我留下的印象很深刻。在视频上传的时候，为了避免上传大视频导致上传时间过长，选用了分片上传的技术，前端将大视频进行拆分，一片一片上传，后端进行存储并记录分片数量，这样带来的好处是：能够让拓展为点断点续传和秒传两个功能，让用户能够感知到上传进度，避免网络问题导致重传的问题。但对于视频的处理并没有处理，用户上传的视频格式是什么就存的什么，考虑的优化点：做个定时任务，使用 FFmpeg 对上传的视频进行统一转码为 m3u8 格式，m3u8 格式视频文件能够很好的支持续播，能够根据片数播放。</p><h2 id="发展计划" tabindex="-1"><a class="header-anchor" href="#发展计划"><span>发展计划</span></a></h2><p>目前的发展计划是先要学会写代码，再考虑的是使用一些设计模式来写出好代码。此外还需要熟悉系统常用的模块、不断学习新的技术点、学习如何设计、思考问题要考虑长远。不能一味的追求技术，脱离业务的技术就是瞎扯。</p>',11)])])}const d=a(i,[["render",t]]),c=JSON.parse('{"path":"/%E6%9D%82%E8%B0%88/2025%E5%B9%B4%E5%AE%9E%E4%B9%A0%E7%AC%AC%E4%B8%80%E9%98%B6%E6%AE%B5%E6%80%BB%E7%BB%93.html","title":"2025年实习第一阶段总结","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"系统熟悉度","slug":"系统熟悉度","link":"#系统熟悉度","children":[]},{"level":2,"title":"专业技能","slug":"专业技能","link":"#专业技能","children":[]},{"level":2,"title":"个人感受","slug":"个人感受","link":"#个人感受","children":[]},{"level":2,"title":"发展计划","slug":"发展计划","link":"#发展计划","children":[]}],"git":{},"filePathRelative":"杂谈/2025年实习第一阶段总结.md"}');export{d as comp,c as data};
